package ru.neverland.townymarket;
import java.util.*;
public final class MarketFundingSmoke{
 static int checks;static void check(boolean b,String why){if(!b)throw new AssertionError(why);checks++;}static void rejects(Runnable r){try{r.run();}catch(RuntimeException expected){checks++;return;}throw new AssertionError("accepted wrong receipt");}
 public static void main(String[]args){var order=UUID.randomUUID();var t=new MarketFunding.Terms(MarketFunding.debit(order),UUID.randomUUID(),UUID.randomUUID(),550000,"infrastructure","Exact city purchase");var row=new HashMap<String,Object>();row.put("operation",t.operation().toString());row.put("town",t.town().toString());row.put("actor",t.actor().toString());row.put("cents",t.cents());row.put("category",t.category());row.put("reason",t.reason());row.put("owner",MarketFunding.OWNER);row.put("source","trade");row.put("kind","DEBIT");row.put("backingDebit","");row.put("backingAvailable",true);row.put("status","PAID");check(t.result(row)==MarketFunding.Result.PAID,"exact backed receipt accepted");
 for(var key:List.of("operation","town","actor","cents","category","reason","owner","source","kind","backingDebit")){var bad=new HashMap<>(row);bad.put(key,key.equals("cents")?550001L:"different");rejects(()->t.result(bad));}for(Object amount:List.of(Double.NaN,Double.POSITIVE_INFINITY,550000.1,"550000")){var bad=new HashMap<>(row);bad.put("cents",amount);rejects(()->t.result(bad));}var lost=new HashMap<>(row);lost.put("backingAvailable",false);check(t.result(lost)==MarketFunding.Result.REVIEW,"spent or refunded debit is not payment");for(var status:List.of("PREPARED","INVOKING","REVIEW","REJECTED")){var changed=new HashMap<>(row);changed.put("status",status);check(t.result(changed)==(status.equals("REVIEW")?MarketFunding.Result.REVIEW:status.equals("REJECTED")?MarketFunding.Result.REJECTED:MarketFunding.Result.WAIT),"known receipt phase "+status);}check(t.result(Map.of("operation",t.operation().toString(),"status","ABSENT"))==MarketFunding.Result.WAIT,"matching absent may request same stable operation");rejects(()->t.result(Map.of("operation",UUID.randomUUID().toString(),"status","ABSENT")));rejects(()->new MarketFunding.Payment("DIRECT",t));rejects(()->new MarketFunding.Payment("TREASURY",null));check(MarketFunding.debit(order).equals(t.operation())&&!MarketFunding.debit(UUID.randomUUID()).equals(t.operation()),"stable per purchase ID");System.out.println("MarketFundingSmoke PASS "+checks+" checks");}
}
